CREATE TABLE core.T_FACT_DELIVERY_PERFORMANCE (
   inbound_dispo_order_pos_sid         NUMBER          NOT NULL COMMENT 'The unique identifier (surrogate key) for the disposition position.',
   dispo_week                          NUMBER          COMMENT 'The dispo week.',
   order_dt                            DATE            COMMENT 'A date when the order was placed',
   dispo_nr                            VARCHAR(20)     COMMENT 'A numeric or alphanumeric value which identifies the disposition for the business.',
   dispo_descr                         VARCHAR(100)    COMMENT 'The description of the disposition.  It contains temperature, last mile crossdock and destination country.',
   order_reference_nr                  VARCHAR(250)    COMMENT '14 digit number containing info about log-type (digits 1-2), main cross-dock (digits 3-5), delivery date at the cross-dock (digits 6-11) and receiving regional subsidiary (digits 12-14)',
   purchase_order_nr                   VARCHAR(20)     COMMENT 'Purchase order number of Wawi',
   route_descr                         VARCHAR(250)    COMMENT 'Description of the planned route',
   departure_site_sid                  NUMBER          NOT NULL COMMENT 'The unique identifier (surrogate key) for the site.',
   destination_site_sid                NUMBER          NOT NULL COMMENT 'The unique identifier (surrogate key) for the site.',
   supplier_sid                        NUMBER          COMMENT 'The unique identifier of the delivering party, e.g. the supplier.',
   hauler_sid                          NUMBER          NOT NULL COMMENT 'The hauler who runs the crossdock.',
   logistic_type_cd                    VARCHAR(20)     NOT NULL COMMENT 'The code for the type of the logistic, e.g. SaL (Sammelladung / Sammellogistik) and KoL (Komplettladung / Direktlogistik)',
   logistic_temp_cd                    VARCHAR(20)     NOT NULL COMMENT 'The code for the type of the temperature zone, e.g. TK, TL.',
   transport_service_type_cd           VARCHAR(20)     NOT NULL COMMENT 'The code for the type of the transport service, e.g. "Vorlauf" or "Zwischenlauf"',
   bus_country_cd                      VARCHAR(2)      COMMENT 'A two-character code according to the business definition of Kaufland or Lidl.',
   product_sid                         NUMBER          COMMENT 'The unique identifier of the product.',
   product_variant_sid                 NUMBER          COMMENT 'The unique identifier of the product variant.',
   prod_variant_nan_nr                 VARCHAR(50)     COMMENT 'National product number of product variant',
   pallet_type_cd                      VARCHAR(20)     COMMENT 'Pallet code of the fact row',
   double_deck_fg                      BOOLEAN         COMMENT 'Indicates whether two pallet units can be placed on top of each other. if so, then 2 order units with pallet storage space factor = 1 occupy one storage space',
   storage_space_qty                   NUMBER(38, 5)   COMMENT 'Needed storage space.',
   pallet_cnt                          NUMBER          COMMENT 'The total number of pallets that have been ordered.',
   total_order_pallet_cnt              NUMBER(38, 5)   COMMENT 'Total quantity of pallets per dispo order reference ',
   missing_pallet_cnt                  NUMBER          COMMENT 'Quantity of pallets which were not delivered',
   total_order_missing_pallet_cnt      NUMBER(38, 5)   COMMENT 'Total quantity of missing pallets per dispo order reference ',
   equipment_type_cd                   VARCHAR(20)     COMMENT 'The type discriminator for this equipment, i.e. vehicle(truck)',
   distance_km_meas                    NUMBER(38, 5)   COMMENT 'Distance of route segment in km',
   agmt_co2_emission_kg_meas           NUMBER(38, 5)   COMMENT 'Emission amount  of Carbon Dioxide in Kg',
   supplier_price_validity_period_from_tmsp TIMESTAMP_TZ(9) COMMENT 'Validity start of brutto price',
   supplier_price_validity_period_to_tmsp TIMESTAMP_TZ(9) COMMENT 'Validity End of brutto price',
   supplier_curr_cd                    VARCHAR(3)      COMMENT 'A three-character code for a currency according to ISO 4217. E.g.: ''EUR'', ''USD'', ''GBP'', …',
   supplier_price_per_vehicle_val      NUMBER(38, 5)   COMMENT 'Price asked by Supplier for a transport . Calculated Amout for a full vehicle',
   supplier_price_per_pallet_val       NUMBER(38, 5)   COMMENT 'Price asked by Supplier for a transport  Calculated Amout per EP Pallet',
   hauler_curr_cd                      VARCHAR(3)      COMMENT 'A three-character code for a currency according to ISO 4217. E.g.: ''EUR'', ''USD'', ''GBP'', …',
   hauler_price_validity_period_from_tmsp TIMESTAMP_TZ(9) COMMENT 'Validity start of netto price',
   hauler_price_validity_period_to_tmsp TIMESTAMP_TZ(9) COMMENT 'Validity start of netto price',
   hauler_price_per_vehicle_val        NUMBER(38, 5)   COMMENT 'Price asked by Hauler for a transport . Calculated Amout for a full vehicle',
   hauler_price_per_pallet_val         NUMBER(38, 5)   COMMENT 'Price asked by Hauler for a transport  Calculated Amout for EP Pallet',
   hauler_delivery_reference_nr        VARCHAR(20)     COMMENT 'Delivery reference in hauler system',
   inbound_logistics_partner_name      VARCHAR(100)    COMMENT 'A name of hauler transporting goods',
   logistics_partner_name              VARCHAR(100)    COMMENT 'A name of hauler transporting goods',
   delivered_pallet_cnt                NUMBER          COMMENT 'Quantity of delivered pallets according to hauler',
   ontime_pallet_cnt                   NUMBER          COMMENT 'Quantity of delivered pallets on time',
   hauler_missing_pallet_cnt           NUMBER          COMMENT 'Quantity of pallets which were not delivered according to hauler',
   tgt_departure_dt                    DATE            COMMENT 'Target departure date to destination',
   tgt_delivery_dt                     DATE            COMMENT 'Target deliivery date  to destination',
   dept_departure_tmsp                 TIMESTAMP_LTZ   COMMENT 'The time when the truck leaves the  departure premises after all tasks (unloading, paperwork, etc.) are finished.',
   dest_arrival_tmsp                   TIMESTAMP_LTZ   COMMENT 'The exact time a truck (LKW) arrives at the destination premises delivering the goods from the previous location',
   dest_punctuality_cd                 VARCHAR(20)     COMMENT 'Destination Punctuality defining if delivery to RDC  is late or on time',
   dest_punctuality_pct                NUMBER(38, 5)   COMMENT 'Destination Punctuality defining if delivery to RDC  is late or on time on order level',
   dest_order_punctuality_pct          VARCHAR(20)     COMMENT 'Destination (RDC or XDOCK) punctuality percentage',
   rdc_delivery_dt                     DATE            COMMENT 'Date of delivery to regional distribution center',
   rdc_punctuality_cd                  VARCHAR(20)     COMMENT 'RDC Punctuality defining if delivery to RDC  is late or on time',
   rdc_punctuality_pct                 VARCHAR(20)     COMMENT 'RDC Punctuality percentage defining if delivery to RDC  is late or on time',
   delivery_progress_pct               NUMBER(38, 5)   COMMENT 'A percentage of delivery',
   last_mile_punctuality_cd            VARCHAR(20)     COMMENT 'Last Punctuality defining if delivery is late or on time',
   ready_for_collection_dt             DATE            COMMENT 'This time when the carrier or a responsible party was notified that the goods were available to be collected.',
   latest_delivery_dt                  DATE            COMMENT 'The planned reception time at ELM.',
   latest_loading_release_dt           DATE            COMMENT 'The last possible time a truck can arrive and pick up goods to ensure they arrive on time. This is a target timestamp that''s either set by the carrier or is a predefined timestamp.',
   advised_for_collection_dt           DATE            COMMENT 'The initial planned timestamp for goods collection, as set by the hauler. This represents the first scheduled date and time for pickup.',
   collected_dt                        DATE            COMMENT 'The actual time the goods are picked up.',
   unloaded_at_wh_dt                   DATE            COMMENT 'The time the truck driver states they were at the warehouse.',
   order_availability_status_cd        VARCHAR(20)     COMMENT 'Is order available for pick up',
   order_availability_punctuality_cd   VARCHAR(20)     COMMENT 'Is pickup scheduled on time',
   pickup_notification_status_cd       VARCHAR(20)     COMMENT 'Pickup Notification status',
   pickup_punctuality_cd               VARCHAR(20)     COMMENT 'Pickup Punctuality status code',
   hauler_delivery_punctuality_cd      VARCHAR(20)     COMMENT 'Hauler delivery punctuality code',
   delivery_punctuality_cd             VARCHAR(20)     COMMENT 'Delivery punctuality code',
   preparation_punctuality_status_cd   VARCHAR(20)     COMMENT 'Delivery punctuality status',
   preparation_punctuality_pct         NUMBER(38, 5)   COMMENT 'Delivery punctuality percentage',
   is_empty_stock_fg                   BOOLEAN         COMMENT 'Is empty stock',
   dwh_created_tmsp                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
   dwh_updated_tmsp                    TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was last updated.',   
   CONSTRAINT PK_T_FACT_DELIVERY_PERFORMANCE PRIMARY KEY (inbound_dispo_order_pos_sid, departure_site_sid, hauler_sid, logistic_type_cd, logistic_temp_cd) NOT ENFORCED 
)  COMMENT = 'This table is a detailed transaction-level fact table designed to measure the end-to-end performance and accuracy of the Direct Collective Logistics (Direkt Sammellogistik) and Cross-Dock (X-Dock) process.';
